package com.oldvicios;

import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Card de aviso/evento. Fechado: imagem, título, data e "Ver mais". Aberto: + texto completo.
 */
class CardPanel extends JPanel
{
	// Largura usada antes do card ser exibido (depois ela acompanha a largura real do card)
	private static final int DEFAULT_IMAGE_WIDTH = 190;
	// Largura do texto antes do card ser exibido (depois acompanha a largura real do card)
	private static final int DEFAULT_TEXT_WIDTH = 180;
	private static final ZoneId BRT = ZoneId.of("America/Sao_Paulo");
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("dd/MM");

	private final JLabel image = new JLabel();
	private final JLabel title = new JLabel();
	private final String titleHtml;
	private final String bodyHtml;
	private int textWidth;
	private final JLabel body = new JLabel();
	private final JLabel toggle = new JLabel();
	private boolean expanded;
	private BufferedImage source;
	private int imageWidth;

	enum Kind
	{
		NOTICE,
		EVENT
	}

	CardPanel(ContentCard card, Kind kind)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(6, 6, 8, 6));

		image.setAlignmentX(Component.LEFT_ALIGNMENT);
		image.setVisible(false);
		add(image);

		// A imagem ocupa a largura toda do card, qualquer que seja a largura do painel
		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				renderImage();
				renderText();
			}
		});

		titleHtml = escape(card.title);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(Box.createVerticalStrut(4));
		add(title);

		String dateText = formatDate(card.date, kind);
		if (card.pinned)
		{
			dateText = dateText == null ? "Fixado" : "Fixado · " + dateText;
		}
		if (dateText != null)
		{
			JLabel date = new JLabel(dateText);
			date.setFont(FontManager.getRunescapeSmallFont());
			date.setForeground(kind == Kind.EVENT ? OldViciosPanel.YELLOW : ColorScheme.LIGHT_GRAY_COLOR);
			date.setAlignmentX(Component.LEFT_ALIGNMENT);
			add(date);
		}

		boolean hasText = card.text != null && !card.text.isEmpty();
		bodyHtml = hasText ? markdownToHtml(card.text) : "";
		body.setFont(FontManager.getRunescapeSmallFont());
		body.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.setVisible(false);
		add(Box.createVerticalStrut(4));
		add(body);

		if (hasText)
		{
			toggle.setFont(FontManager.getRunescapeSmallFont());
			toggle.setForeground(OldViciosPanel.YELLOW);
			toggle.setAlignmentX(Component.LEFT_ALIGNMENT);
			// O card inteiro abre/fecha. mousePressed (e não mouseClicked) porque o clicked
			// é descartado se o mouse mexer um pixel entre apertar e soltar.
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (javax.swing.SwingUtilities.isLeftMouseButton(e))
					{
						setExpanded(!expanded);
					}
				}
			});
			add(Box.createVerticalStrut(2));
			add(toggle);
			setExpanded(false);
		}
		renderText();
	}

	/** Reaplica o HTML com a largura atual do card, pra quebrar linha sem cortar o texto. */
	private void renderText()
	{
		Insets insets = getInsets();
		int width = getWidth() > 0 ? getWidth() - insets.left - insets.right - 4 : DEFAULT_TEXT_WIDTH;
		if (width <= 0 || width == textWidth)
		{
			return;
		}
		textWidth = width;
		title.setText(html(titleHtml, width, false));
		// Justificado: na coluna estreita, o alinhamento à esquerda deixava uma sobra grande na direita
		body.setText(bodyHtml.isEmpty() ? "" : html(bodyHtml, width, true));
		revalidate();
		repaint();
	}

	private void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		body.setVisible(expanded);
		// A fonte do RuneScape não tem setas (▾▴); + e - existem
		toggle.setText(expanded ? "- Ver menos" : "+ Ver mais");
		revalidate();
		repaint();
	}

	// Must be called on the Swing EDT.
	void setImage(BufferedImage source)
	{
		if (source == null)
		{
			return;
		}
		this.source = source;
		imageWidth = 0;
		renderImage();
	}

	private void renderImage()
	{
		if (source == null)
		{
			return;
		}
		Insets insets = getInsets();
		int width = getWidth() > 0 ? getWidth() - insets.left - insets.right : DEFAULT_IMAGE_WIDTH;
		if (width <= 0 || width == imageWidth)
		{
			return;
		}
		imageWidth = width;

		// Igual a "width: 100%; height: auto" no CSS: cabe na largura e a altura acompanha, sem cortar
		int height = Math.max(1, Math.round(source.getHeight() * (width / (float) source.getWidth())));
		image.setIcon(new ImageIcon(source.getScaledInstance(width, height, java.awt.Image.SCALE_SMOOTH)));
		image.setVisible(true);
		revalidate();
		repaint();
	}

	@Override
	public Dimension getMaximumSize()
	{
		// BoxLayout estica na largura, mas não na altura
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	/** "31/10 às 20h · em 16 dias" (evento) ou "Publicado em 15/10" (aviso), no horário de Brasília. */
	static String formatDate(String iso, Kind kind)
	{
		if (iso == null)
		{
			return null;
		}
		ZonedDateTime date;
		try
		{
			date = ZonedDateTime.parse(iso).withZoneSameInstant(BRT);
		}
		catch (Exception e)
		{
			return null;
		}
		if (kind == Kind.NOTICE)
		{
			return "Publicado em " + date.format(DAY);
		}

		String hour = date.getMinute() == 0
			? date.getHour() + "h"
			: date.getHour() + "h" + String.format("%02d", date.getMinute());
		long days = ChronoUnit.DAYS.between(LocalDate.now(BRT), date.toLocalDate());
		String relative = days <= 0 ? "hoje" : days == 1 ? "amanhã" : "em " + days + " dias";
		return date.format(DAY) + " às " + hour + " · " + relative;
	}

	static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Markdown simples do Discord → HTML do Swing: **negrito**, *itálico*, __sublinhado__, [texto](link) e quebras de linha. */
	static String markdownToHtml(String markdown)
	{
		return escape(markdown)
			.replaceAll("\\*\\*(.+?)\\*\\*", "<b>$1</b>")
			.replaceAll("__(.+?)__", "<u>$1</u>")
			.replaceAll("\\*(.+?)\\*", "<i>$1</i>")
			.replaceAll("\\[(.+?)]\\(\\S+?\\)", "$1")
			.replace("\n", "<br>");
	}

	/**
	 * Em "pt", não "px": o HTML do Swing multiplica px por 1,3, então width:214px montava o texto
	 * com 278 pixels e cortava o fim de cada linha. pt é 1 pixel na tela.
	 */
	static String html(String content, int width, boolean justify)
	{
		String align = justify ? ";text-align:justify" : "";
		return "<html><div style='width:" + width + "pt" + align + "'>" + content + "</div></html>";
	}
}

package com.oldvicios;

/** Item das abas Avisos/Eventos, no formato de /v1/plugin/notices e /v1/plugin/events. */
class ContentCard
{
	int id;
	String title;
	String text;
	// Muda quando a staff troca a imagem; null = sem imagem. A imagem vem de
	// /v1/plugin/{notices|events}/{id}/image: o plugin nunca recebe URL de imagem do servidor.
	String imageVersion;
	// ISO-8601. Avisos: data de publicação; eventos: data do evento.
	String date;
	boolean pinned;
}

package com.oldvicios;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.util.Collections;
import java.util.List;
import javax.imageio.ImageIO;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Cliente HTTP da API do OldVicios. Todas as chamadas usam enqueue() (thread pool do OkHttp),
 * nunca a client thread.
 */
@Slf4j
@Singleton
class OldViciosApi
{
	/** Versão do plugin, enviada em toda chamada (X-OV-Version). Manter igual a runelite-plugin.properties. */
	static final String VERSION = "0.1.2";

	private static final String BASE_URL = "https://api.oldvicios.com.br/v1/plugin";
	private static final String ACCOUNT_SALT = "oldvicios-plugin-v1";
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	/**
	 * Identificador anônimo da conta: sha256(accountHash + salt). O accountHash do RuneLite
	 * é fixo por conta OSRS, então funciona em qualquer PC e sobrevive a troca de nick.
	 */
	static String accountId(long accountHash)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest((accountHash + ":" + ACCOUNT_SALT).getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(hash.length * 2);
			for (byte b : hash)
			{
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}

	/** Resultado de uma chamada: status HTTP (0 = falha de rede) + corpo `data` quando houver. */
	static final class Result
	{
		final int status;
		final JsonObject data;
		final JsonArray dataArray;
		final String error;

		Result(int status, JsonObject data, JsonArray dataArray, String error)
		{
			this.status = status;
			this.data = data;
			this.dataArray = dataArray;
			this.error = error;
		}

		boolean ok()
		{
			return status == 200 && data != null;
		}
	}

	void authenticate(String accountId, String playerName, Consumer<Result> callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("playerName", playerName);
		Request request = new Request.Builder()
			.url(BASE_URL + "/auth")
			.header("X-OV-Account", accountId)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		send(request, callback);
	}

	void submitLoot(String accountId, JsonObject payload, byte[] screenshotPng, Consumer<Result> callback)
	{
		MultipartBody.Builder body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload", gson.toJson(payload));
		if (screenshotPng != null)
		{
			body.addFormDataPart("file", "drop.png", RequestBody.create(PNG, screenshotPng));
		}
		Request request = new Request.Builder()
			.url(BASE_URL + "/loot")
			.header("X-OV-Account", accountId)
			.post(body.build())
			.build();
		send(request, callback);
	}

	/**
	 * Lista de cards de uma aba ("notices" ou "events"). Exige a conta conectada e ainda no clã:
	 * 401/403 chama onDenied (o painel limpa o conteúdo); outros erros mantêm o que já está na tela.
	 */
	void fetchCards(String tab, String accountId, Consumer<List<ContentCard>> onSuccess, Runnable onDenied)
	{
		Request request = new Request.Builder()
			.url(BASE_URL + "/" + tab)
			.header("X-OV-Account", accountId)
			.cacheControl(CacheControl.FORCE_NETWORK)
			.get()
			.build();
		send(request, result ->
		{
			if (result.status == 401 || result.status == 403)
			{
				onDenied.run();
				return;
			}
			if (result.status != 200 || result.dataArray == null)
			{
				return;
			}
			List<ContentCard> cards = gson.fromJson(result.dataArray, new TypeToken<List<ContentCard>>()
			{
			}.getType());
			onSuccess.accept(cards != null ? cards : Collections.emptyList());
		});
	}

	/** Notificações depois do cursor. since null = só pega o cursor atual. accountId opcional. */
	void fetchUpdates(String accountId, Integer since, Consumer<Result> callback)
	{
		String url = BASE_URL + "/updates" + (since != null ? "?since=" + since : "");
		Request.Builder request = new Request.Builder().url(url).cacheControl(CacheControl.FORCE_NETWORK).get();
		if (accountId != null)
		{
			request.header("X-OV-Account", accountId);
		}
		send(request.build(), callback);
	}

	/**
	 * Baixa a imagem de um card (fora da client thread). null em caso de erro.
	 * A URL é montada aqui a partir de BASE_URL, nunca recebida do servidor, então o plugin
	 * só fala com api.oldvicios.com.br.
	 */
	void fetchImage(String tab, int cardId, String accountId, Consumer<BufferedImage> callback)
	{
		HttpUrl url = HttpUrl.get(BASE_URL).newBuilder()
			.addPathSegment(tab)
			.addPathSegment(Integer.toString(cardId))
			.addPathSegment("image")
			.build();
		Request request = new Request.Builder()
			.url(url)
			.header("X-OV-Account", accountId)
			.header("X-OV-Version", VERSION)
			.get()
			.build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("OldVicios image download failed: {}", url, e);
				callback.accept(null);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body(); InputStream in = body == null ? null : body.byteStream())
				{
					callback.accept(response.isSuccessful() && in != null ? ImageIO.read(in) : null);
				}
				catch (IOException e)
				{
					log.debug("OldVicios image decode failed: {}", url, e);
					callback.accept(null);
				}
			}
		});
	}

	private void send(Request unversioned, Consumer<Result> callback)
	{
		// Toda chamada pra API leva a versão, pro backend saber quem está desatualizado
		Request request = unversioned.newBuilder().header("X-OV-Version", VERSION).build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("OldVicios API request failed: {}", request.url(), e);
				callback.accept(new Result(0, null, null, "network_error"));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					JsonObject json = responseBody == null ? null : gson.fromJson(responseBody.charStream(), JsonObject.class);
					JsonObject data = json != null && json.has("data") && json.get("data").isJsonObject()
						? json.getAsJsonObject("data") : null;
					JsonArray dataArray = json != null && json.has("data") && json.get("data").isJsonArray()
						? json.getAsJsonArray("data") : null;
					String error = json != null && json.has("error") && !json.get("error").isJsonNull()
						? json.get("error").getAsString() : null;
					callback.accept(new Result(response.code(), data, dataArray, error));
				}
				catch (Exception e)
				{
					log.debug("OldVicios API bad response: {}", request.url(), e);
					callback.accept(new Result(response.code(), null, null, "bad_response"));
				}
			}
		});
	}
}

package com.oldvicios;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup(OldViciosConfig.GROUP)
public interface OldViciosConfig extends Config
{
	String GROUP = "oldvicios";

	// Texto exigido pelo RuneLite em toggles que mandam dados pra servidor de terceiros
	String THIRD_PARTY_WARNING = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	String DEFAULT_LOOT_MESSAGE = "%USERNAME% has looted: \n\n%LOOT%\nFrom: %SOURCE%";

	@ConfigSection(
		name = "Geral",
		description = "Configurações gerais do plugin",
		position = -1
	)
	String generalSection = "general";

	@ConfigItem(
		keyName = "sidebarPriority",
		name = "Posição na sidebar",
		description = "Posição do ícone do OldVicios na sidebar do RuneLite. Quanto menor, mais pra cima",
		section = generalSection,
		position = 0
	)
	@Range(min = -10, max = 100)
	default int sidebarPriority()
	{
		return 1;
	}

	@ConfigSection(
		name = "Drops",
		description = "Envio de drops para o Discord do OldVicios",
		position = 0
	)
	String dropsSection = "drops";

	@ConfigSection(
		name = "Notificações",
		description = "Avisos de novos eventos, avisos da staff e mensagens pra você",
		position = 1
	)
	String notificationsSection = "notifications";

	@ConfigItem(
		keyName = "sendDrops",
		name = "Enviar drops",
		description = "Publica seus drops no Discord do OldVicios",
		warning = THIRD_PARTY_WARNING,
		section = dropsSection,
		position = 0
	)
	default boolean sendDrops()
	{
		// Regra do Plugin Hub: envio pra servidor de terceiros começa desligado (opt-in)
		return false;
	}

	@ConfigItem(
		keyName = "sendPkDrops",
		name = "Enviar drops PK",
		description = "Publica seus drops de PvP no canal de PK do Discord do OldVicios",
		warning = THIRD_PARTY_WARNING,
		section = dropsSection,
		position = 1
	)
	default boolean sendPkDrops()
	{
		return false;
	}

	@ConfigItem(
		keyName = "lootMessage",
		name = "Mensagem do drop",
		description = "Texto da mensagem no Discord. Use %USERNAME% (seu nome), %LOOT% (itens), %SOURCE% (boss/origem), "
			+ "%COUNT% (kill count), %TOTAL_VALUE% (valor total) e %WORLD% (mundo)",
		section = dropsSection,
		position = 2
	)
	default String lootMessage()
	{
		return DEFAULT_LOOT_MESSAGE;
	}

	@ConfigItem(
		keyName = "chatNotifications",
		name = "Mensagem no chat",
		description = "Mostra no chat do jogo quando sai um evento, um aviso ou uma mensagem pra você",
		section = notificationsSection,
		position = 0
	)
	default boolean chatNotifications()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notification",
		name = "Notificação do RuneLite",
		description = "Notificação do RuneLite (sistema, som, piscar a tela...). Clique na engrenagem pra escolher como receber",
		section = notificationsSection,
		position = 1
	)
	default Notification notification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "hasConnected",
		name = "",
		description = "Se este RuneLite já conectou ao OldVicios (muda a mensagem da tela de boas-vindas)",
		hidden = true
	)
	default boolean hasConnected()
	{
		return false;
	}
}

